from _lib import File
F=File('pre2020_yamaha250','o-y25','Yamaha YZ250F 2010-2018 by generation (2010-2011, 2012-2013 carburetted; 2014-2018 reverse-cylinder EFI): what changed, dyno and weight, jetting, tester settings, known problems and fixes (knowledge push 2026-11)','Yamaha',['YZ250F'],list(range(2010,2019)))
R=F.R; M='magazine'; C=['YZ250F']

# ---------------- 2010-2011
s=F.src(M,"Motocross Action - 2010 Yamaha YZ250F race test","https://motocrossactionmag.com/real-tests-2010-mxa-race-test-of-the-yamaha-yz250f","2009")
G=[2010,2011]
R('identity','2010 redesign',C,G,"The 2010 YZ250F got a new aluminium perimeter frame (head tube 7 mm back and 12 mm lower), lower and narrower radiators, a longer and quieter muffler, a stronger clutch, slightly taller third and fourth gears, taller bar mounts and footpegs, a flatter seat and a smaller tank. It kept the five-valve engine and the Keihin FCR carburettor. Fork offset stayed at 25 mm. The 2011 is the same bike.",{'offset_mm':25,'fuel_system':'Keihin FCR carburettor'},'OEM',s)
R('power_feel','2010-2011 dyno',C,G,"On a magazine dyno the 2010 YZ250F (and the unchanged 2011) made 35.88 hp at 11,500 rpm and 18.95 lb-ft. It is very quick off the bottom and best from low to mid, with little pull above about 9,500 rpm. It measured 95.5 dB.",{'peak_hp':35.88,'peak_rpm':11500,'peak_torque_lbft':18.95},'MEASURED',s,'high')
R('setups','2010-2011 tester settings',C,G,"A magazine test crew's 2010 YZ250F setup: fork 0.46 kg/mm springs (stock 0.45; stiffer again over about 160 lb) with oil dropped to 330 cc (stock 350) to remove a mid-stroke spike, compression 2 clicks out (stock 8), rebound 8 out (stock 10), legs 5 mm up. Shock 5.3 kg/mm spring, 105 mm sag (stock recommendation 100), high-speed compression 2-1/4 turns out (stock 1-3/4), low-speed 7 clicks out (stock 9), rebound 9 out (stock 10). A 48-tooth rear sprocket in place of the stock 49 stretches the short powerband a little.",{'fork':'0.46 kg/mm, 330 cc, comp 2 out (stock 8), reb 8 out (stock 10), 5 mm up','shock':'5.3 kg/mm, sag 105 mm, HSC 2-1/4 turns, LSC 7 out, reb 9 out','gearing':'13/48 (stock 13/49)'},'TUNER',s)
R('setups','2010-2011 jetting',C,G,"Stock jetting on the 2010-2011 YZ250F (37 mm Keihin FCR): 180 main, 45 pilot, NDJR needle on the 4th clip from the top, 70 leak jet, fuel screw 1-3/4 turns out. Testers ran the fuel screw at 3/4 turn. At high altitude go to a 178 main and the 3rd clip; in cold weather a 182 main with the fuel screw at 2-1/4 turns.",{'main':180,'pilot':45,'needle':'NDJR, 4th clip','leak_jet':70,'fuel_screw_stock':'1-3/4 turns','fuel_screw_tested':'3/4 turn','altitude':'178 main, 3rd clip','cold':'182 main, 2-1/4 turns'},'TUNER',s)
# ---------------- 2012-2013
s=F.src(M,"Motocross Action - 2012 Yamaha YZ250F test","https://motocrossactionmag.com/mxas-2012-yamaha-yz250f-motocross-test-the-last-250-four-stroke-with-a-spritzen-puffer","2011")
G=[2012,2013]
R('identity','2012 changes',C,G,"2012 YZ250F changes: a 39 mm carburettor (was 37), an airbox cage with 50% more volume, a piston 8.7% lighter, a muffler core 8 mm smaller, a 50-tooth rear sprocket (was 49), a new frame, fork offset reduced from 25 mm to 22 mm, 0.46 kg/mm fork springs (was 0.45), a 16 mm shock shaft (was 18) and black rims. The 2013 added only graphics, black bars and a white rear fender. These were the last carburetted 250 four-stroke motocrossers.",{'carb_mm':39,'offset_mm':22,'rear_sprocket':50,'fork_spring':'0.46 kg/mm'},'OEM',s)
R('power_feel','2012-2013 dyno and weight',C,G,"On a magazine dyno the 2012-2013 YZ250F made 37.13 hp at 11,500 rpm and 19.55 lb-ft. It weighed 218 lb. Strong from 6,000 to 9,000 rpm and broad, but not a revver and down on peak power. Sound was 92.7 dB; the quiet muffler costs power.",{'peak_hp':37.13,'peak_rpm':11500,'peak_torque_lbft':19.55,'weight_lb':218},'MEASURED',s,'high')
R('setups','2012-2013 tester settings',C,G,"A magazine test crew's 2012-2013 YZ250F setup: fork stock 0.46 kg/mm springs, 340 cc oil (stock 345; lighter riders can drain 5 cc more a leg to cure mid-stroke harshness), compression 9 clicks out (stock 10), rebound 10 out, legs 5 mm up. Shock 5.3 kg/mm spring (5.5 for heavier riders if free sag falls outside 30-40 mm), 100 mm sag, high-speed compression 2 turns out (stock 1-3/4), low-speed 10 clicks out (stock 8), rebound 12 out (stock 14). Stock 50-tooth gearing was kept.",{'fork':'340 cc, comp 9 out, reb 10 out, 5 mm up','shock':'5.3 kg/mm, sag 100 mm, HSC 2 turns, LSC 10 out, reb 12 out','free_sag_mm':'30-40'},'TUNER',s)
R('setups','2012-2013 jetting',C,G,"Jetting for the 2012-2013 YZ250F (39 mm Keihin FCR): 185 main, 38 pilot, NFPR needle on the 5th clip from the top, 95 leak jet. Testers ran the fuel screw 1 turn out (stock 2) and turned it in further in hot weather. The stock settings suit sea level; they are not right for high elevation or cold.",{'main':185,'pilot':38,'needle':'NFPR, 5th clip','leak_jet':95,'fuel_screw_stock':'2 turns','fuel_screw_tested':'1 turn'},'TUNER',s)
R('engine_mods','2012-2013 first power steps',C,G,"On the 2012-2013 YZ250F the restrictive muffler and intake are the first things to fix: a full aftermarket exhaust improved mid and top in testing, and an aftermarket intake kit added about 1 hp on the dyno.",{'intake_kit_hp':'about 1'},'MEASURED',s)
R('known_issues','2010-2013 weak points',C,[2010,2011,2012,2013],"Tester complaints on the carburetted 2010-2013 YZ250F: a short powerband that makes gearing hard to get right, fork mid-stroke harshness (cured with oil level), a shock that hops under hard braking (back off high-speed compression and soften low-speed), side panels that barely take a number, and on 2012-2013 bikes black rims that scratch quickly. Durability was rated very good.",{},'TUNER',s)

# ---------------- 2014-2018
s=F.src(M,"Motocross Action - 2014 Yamaha YZ250F test","https://motocrossactionmag.com/mxas-2014-yamaha-yz250f-motocross-test-everybody-loves-an-underdog-and-if-you-dont-love-it-get-used-to-following-it","2013")
G=[2014,2015,2016,2017,2018]
R('identity','2014 redesign',C,G,"The 2014 YZ250F was all new: a rearward-slanted, reversed four-valve cylinder with fuel injection (44 mm throttle body, 10-hole injector), the airbox at the front and the exhaust wrapping around the cylinder, a new frame shared in layout with the YZ450F, stiffer springs (fork 4.7 N/mm, was 4.5), a front axle 2 mm larger and 10 mm more fork travel. Steering geometry was carried over from 2013. Weight rose from 218 to 221 lb. This platform ran 2014-2018.",{'throttle_body_mm':44,'fork_spring':'4.7 N/mm','weight_lb':221},'OEM',s)
R('power_feel','2014 dyno',C,[2014],"On a magazine dyno the 2014 YZ250F made 40.61 hp at 12,100 rpm and 20.28 lb-ft, against 37.13 hp for the 2013. Strong right off idle, at its best from 8,000 to 10,000 rpm and flat on top.",{'peak_hp':40.61,'peak_rpm':12100,'peak_torque_lbft':20.28},'MEASURED',s,'high')
R('setups','2014 tester settings',C,[2014],"A magazine test crew's 2014 YZ250F setup: fork stock 4.7 N/mm springs, 330 cc oil, compression 12 clicks out (stock 8), rebound 12 out (stock 9), legs 5 mm up. Shock 56 N/mm spring, 102 mm sag, high-speed compression 2 turns out (stock 1-1/3), low-speed 12 clicks out (stock 10), rebound 12 out (stock 14).",{'fork':'4.7 N/mm, 330 cc, comp 12 out (stock 8), reb 12 out (stock 9), 5 mm up','shock':'56 N/mm, sag 102 mm, HSC 2 turns, LSC 12 out, reb 12 out'},'TUNER',s)
R('ecu_electronics','2014-2018 Power Tuner maps',C,G,"The 2014-2018 YZ250F is mapped with the handheld GYTR Power Tuner (about $280). It adds no peak power but moves the delivery. Yamaha published two alternative maps: an aggressive one (richer, more advance) that testers preferred on most tracks, and a hard-pack one (leaner, less advance) that gave more top end on fast tracks. Remap after fitting a pipe, porting or changing to race fuel.",{'tool':'GYTR Power Tuner','maps':'aggressive (richer, advanced); hard-pack (opposite)'},'TUNER',s)
s=F.src(M,"Motocross Action - 2015 Yamaha YZ250F test","https://motocrossactionmag.com/2015-yamaha-yz250f","2014")
R('identity','2015 changes',C,[2015],"2015 YZ250F changes: an exhaust cam with the decompression pin moved 6 degrees for easier starting, a reshaped piston ring land to cut oil use, a roller gear-stop lever, a stronger water pump shaft, recalibrated fuel and ignition, a throttle return spring 20% lighter, quarter-turn airbox fasteners, 5 cc more fork oil with less low-speed compression, black rims and a gold chain. List price $7,590.",{'msrp_usd':7590},'OEM',s)
R('power_feel','2015 dyno',C,[2015],"On a magazine dyno the 2015 YZ250F peaked at 41.11 hp, third in the class behind the two Austrian 250s. Strong bottom, broad middle (best from about 8,000 to 10,000 rpm), weaker on top.",{'peak_hp':41.11},'MEASURED',s,'high')
R('setups','2015 tester settings',C,[2015],"A magazine test crew's 2015 YZ250F setup: fork 4.7 N/mm springs (4.5 for light riders, or lower the oil in 5 cc steps), 335 cc oil, compression 14 clicks out (stock 10), rebound 10 out (stock 12), legs 5 mm up. Shock 56 N/mm spring, 102 mm sag, high-speed compression 1-1/4 turns out (stock 1-1/3), rebound 10 out (stock 14), low-speed compression backed well out from the stock 10.",{'fork':'4.7 N/mm, 335 cc, comp 14 out (stock 10), reb 10 out (stock 12), 5 mm up','shock':'56 N/mm, sag 102 mm, HSC 1-1/4 turns, reb 10 out (stock 14)'},'TUNER',s)
s=F.src(M,"Motocross Action - 2016 Yamaha YZ250F race test","https://motocrossactionmag.com/mxa-race-test-2016-yamaha-yz250f","2015")
R('identity','2016 changes',C,[2016],"2016 YZ250F changes: a stronger bridged-box piston 7% lighter with a lighter pin, a re-balanced crank, the judder springs removed from the nine-plate clutch, a narrower neutral detent with reshaped third-to-fifth gear dogs, a gear-stop roller supported on both sides, a softer 54 N/mm shock spring (was 56), less low-speed and more high-speed fork damping, and a 270 mm front disc (was 250). Compression stays 13.5:1.",{'shock_spring':'54 N/mm','front_disc_mm':270,'compression':'13.5:1'},'OEM',s)
R('power_feel','2016 dyno and weight',C,[2016],"On a magazine dyno the 2016 YZ250F made 39.35 hp at 11,800 rpm and 20.44 lb-ft at 8,400 rpm, and weighed 221 lb. It has more torque than its rivals from 5,000 to 9,000 rpm; the best shift point is around 11,500 rpm.",{'peak_hp':39.35,'peak_rpm':11800,'peak_torque_lbft':20.44,'torque_rpm':8400,'weight_lb':221,'shift_rpm':11500},'MEASURED',s,'high')
R('setups','2016 tester settings',C,[2016],"A magazine test crew's 2016 YZ250F setup: fork 4.7 N/mm springs (4.5 for riders under 150 lb), compression 14 clicks out (stock 10), rebound 10 out (stock 12), legs 5 mm up. Shock stock 54 N/mm spring, 102 mm sag, high-speed compression 1-1/2 turns out (stock 1-1/4), low-speed 15 clicks out (stock 12), rebound 10 out (stock 13). Faster riders also tried a 49-tooth rear sprocket.",{'fork':'comp 14 out (stock 10), reb 10 out (stock 12), 5 mm up','shock':'54 N/mm, sag 102 mm, HSC 1-1/2 turns, LSC 15 out, reb 10 out'},'TUNER',s)
s=F.src(M,"Motocross Action - 2017 Yamaha YZ250F race test","https://motocrossactionmag.com/mxa-race-test-2017-yamaha-yz250f","2016")
R('identity','2017 changes',C,[2017,2018],"2017 YZ250F changes: a new head with the intake port raised 4 mm, a shorter velocity stack, more valve lift and stiffer valve springs, a larger head pipe, the rev limit raised to 14,000 rpm, heat-treated cases, a thicker output shaft, wider second and third gears, a stronger connecting rod, swingarm pivot forgings extended 12 mm, larger head stays, steel lower engine mounts, footpegs 5 mm lower, stiffer upper fork tubes and a 4.6 N/mm fork spring (was 4.7). The 2018 added only blue rims and brushed covers.",{'rev_limit_rpm':14000,'fork_spring':'4.6 N/mm'},'OEM',s)
R('power_feel','2017-2018 dyno and weight',C,[2017,2018],"On a magazine dyno the 2017 YZ250F peaked at 40.98 hp, 1 to 1.6 hp more than the 2016 everywhere from 7,000 rpm up, and weighed 222 lb. The 2018 engine is unchanged. Strong low-to-mid torque that pulls through the middle and revs out.",{'peak_hp':40.98,'weight_lb':222},'MEASURED',s,'high')
R('setups','2017-2018 tester settings',C,[2017,2018],"A magazine test crew's 2017 YZ250F setup: fork stock 4.6 N/mm springs, compression 14 clicks out (stock 11), rebound 10 out (stock 12), legs 5 mm up. Shock 54 N/mm spring, 102 mm sag, high-speed compression 1-1/2 turns out (stock 1-1/8), low-speed 15 clicks out (stock 11), rebound 10 out (stock 14). On the mechanically unchanged 2018 the same crew printed 103 mm sag and fork rebound at 14 out. Stock gearing is a 50-tooth rear; a 51 suits tight tracks and slower riders, a 49 lets fast riders carry speed.",{'fork':'4.6 N/mm, comp 14 out (stock 11), reb 10 out (stock 12), 5 mm up','shock':'54 N/mm, sag 102-103 mm, HSC 1-1/2 turns, LSC 15 out, reb 10 out','gearing':'stock 50T; 51T tight tracks; 49T fast riders'},'TUNER',s)
R('known_issues','2014-2018 weak points and fixes',C,G,"Repeated tester findings on the 2014-2018 YZ250F: early bikes had water-pump shaft, gear-stop roller and connecting-rod failures, which Yamaha addressed with stronger parts in 2015, 2016 and 2017; the 250 mm front brake on 2014-2015 bikes is weak (oversize disc), while the 270 mm brake from 2016 is strong but grabby; the airbox fasteners on 2015-2016 bikes fall out or snag; the wrap-around exhaust is hard to remove; the intake is loud and its backfire screen restricts flow (an aftermarket cage and filter kit); the shock hops under hard braking (soften low-speed, adjust high-speed); the bars have a tall, swept bend many riders replace; and the 2016 rear disc could warp.",{},'TUNER',s)
R('chassis','2014-2018 handling character',C,G,"The 2014-2018 YZ250F shares its frame layout with the YZ450F but handles better because the engine is lighter: the front stays planted on turn entry and the rear tracks well through whoops and sweepers. It carries its weight slightly to the rear and feels wide. For stability run a little less sag and drop the fork in the clamps; raising the fork a lot makes the rear feel high.",{},'TUNER',s)

if __name__=='__main__': F.write()
